import type { SseEvent } from "../actor/session-actor";
import { getUser, loadProgram, getQueueItems, getRoutineMappings } from "../storage/queries";
import { getNextRoutine, getCompletedRoutines } from "../domain/queue";
import { computeUpcoming } from "../domain/reflow";
import { setupPage } from "../fragments/setup";
import { carsCard, heroRoutineCard, completedSection, upcomingSection, syncButton } from "../fragments/today";
import { todayString } from "../utils/date";
import { buildContentEvents } from "./build-events";

export interface TodayProjection {
  events: SseEvent[];
  subtitle?: string;
  isSetup: boolean;
}

/** Build SseEvent[] for the Today page — used by the SessionActor DO on connect. */
export async function buildTodayProjection(db: D1Database, userId: string, tz?: string): Promise<TodayProjection> {
  const user = await getUser(db, userId);
  if (!user) {
    return {
      events: buildContentEvents([setupPage()]),
      isSetup: true,
    };
  }

  const { program, programId } = await loadProgram(db, userId);
  if (!program.routines || !program.weekTemplates) {
    throw new Error("Program missing required fields: routines, weekTemplates");
  }
  const routineMap = new Map(program.routines.map((r) => [r.id, r]));
  const dailyRoutine = program.routines.find((r) => r.isDaily);

  const [items, routineMappings] = await Promise.all([
    getQueueItems(db, userId, programId),
    getRoutineMappings(db, userId, programId),
  ]);
  const today = todayString(tz);
  const routineToHevyId = new Map(
    routineMappings.map((m) => [m.program_routine_id, m.hevy_routine_id])
  );

  const dailyDoneToday = dailyRoutine && user.daily_completed_date === today;
  const fragments: string[] = [];

  if (dailyRoutine && !dailyDoneToday) {
    fragments.push(carsCard(dailyRoutine, routineToHevyId.get(dailyRoutine.id)));
  }

  const nextItem = getNextRoutine(items);
  if (nextItem) {
    const routine = routineMap.get(nextItem.routine_id);
    if (routine) {
      fragments.push(heroRoutineCard(routine, nextItem));
    }
  }

  const completed = getCompletedRoutines(items, today);
  const completedData = completed.map((item) => ({
    title: routineMap.get(item.routine_id)?.title ?? item.routine_id,
    hevy_workout_data: item.hevy_workout_data,
  }));
  if (dailyDoneToday) {
    completedData.unshift({ title: dailyRoutine.title, hevy_workout_data: null });
  }
  if (completedData.length > 0) {
    fragments.push(completedSection(completedData));
  }

  const template = program.weekTemplates.find((t) => t.id === user.template_id);
  if (template) {
    const pendingItems = items.filter((i) => i.status === "pending").sort((a, b) => a.position - b.position);
    const upcomingPending = pendingItems.slice(1);
    const jsDay = new Date(today + "T12:00:00Z").getDay();
    const todayDow = jsDay === 0 ? 6 : jsDay - 1;
    const upcoming = computeUpcoming(upcomingPending, template, program.routines, 5, todayDow);
    if (upcoming.length > 0) {
      fragments.push(upcomingSection(upcoming));
    }
  }

  fragments.push(syncButton(user.webhook_id, null, user.last_sync_at, tz));

  return { events: buildContentEvents(fragments), subtitle: program.meta.subtitle, isSetup: false };
}

import type { UserRow, QueueItemRow, ExerciseTemplateMappingRow, RoutineMappingRow, ProgramRow, Program, BenchmarkResultRow } from "../types";
import { sha256Hex, encryptAesGcm } from "../utils/crypto";

export async function getUser(db: D1Database, userId: string): Promise<UserRow | null> {
  return db.prepare("SELECT * FROM users WHERE id = ?").bind(userId).first<UserRow>();
}

export async function upsertUser(
  db: D1Database,
  user: { id: string; active_program: string; template_id: string; start_date: string; hevy_api_key?: string; timezone?: string }
): Promise<void> {
  await db
    .prepare(
      `INSERT INTO users (id, active_program, template_id, start_date, hevy_api_key, timezone)
       VALUES (?, ?, ?, ?, ?, ?)
       ON CONFLICT(id) DO UPDATE SET
         active_program = excluded.active_program,
         template_id = excluded.template_id,
         start_date = excluded.start_date,
         hevy_api_key = COALESCE(excluded.hevy_api_key, users.hevy_api_key),
         timezone = COALESCE(excluded.timezone, users.timezone)`
    )
    .bind(user.id, user.active_program, user.template_id, user.start_date, user.hevy_api_key ?? null, user.timezone ?? null)
    .run();
}

/** Update program fields and return the existing API key in one roundtrip */
export async function updateUserProgram(
  db: D1Database,
  userId: string,
  activeProgram: string,
  templateId: string,
  startDate: string
): Promise<string | null> {
  await db
    .prepare("UPDATE users SET active_program = ?, template_id = ?, start_date = ? WHERE id = ?")
    .bind(activeProgram, templateId, startDate, userId)
    .run();
  const row = await db.prepare("SELECT hevy_api_key FROM users WHERE id = ?").bind(userId).first<{ hevy_api_key: string | null }>();
  return row?.hevy_api_key ?? null;
}

export async function getQueueItems(db: D1Database, userId: string, programId?: number): Promise<QueueItemRow[]> {
  const result = programId != null
    ? await db
        .prepare("SELECT * FROM queue_items WHERE user_id = ? AND program_id = ? ORDER BY position")
        .bind(userId, programId)
        .all<QueueItemRow>()
    : await db
        .prepare("SELECT * FROM queue_items WHERE user_id = ? ORDER BY position")
        .bind(userId)
        .all<QueueItemRow>();
  return result.results;
}

export async function insertQueueItems(
  db: D1Database,
  userId: string,
  items: Array<{ routine_id: string; position: number }>,
  programId?: number
): Promise<void> {
  const stmt = db.prepare(
    "INSERT INTO queue_items (user_id, routine_id, position, program_id) VALUES (?, ?, ?, ?)"
  );
  const batch = items.map((item) => stmt.bind(userId, item.routine_id, item.position, programId ?? null));
  await db.batch(batch);
}

export async function markQueueItemCompleted(
  db: D1Database,
  itemId: number,
  completedDate: string,
  hevyWorkoutId?: string,
  workoutData?: string
): Promise<void> {
  await db
    .prepare(
      "UPDATE queue_items SET status = 'completed', completed_date = ?, hevy_workout_id = ?, hevy_workout_data = ? WHERE id = ?"
    )
    .bind(completedDate, hevyWorkoutId ?? null, workoutData ?? null, itemId)
    .run();
}

/** Batch-mark multiple queue items as completed in a single D1 roundtrip */
export async function batchMarkQueueItemsCompleted(
  db: D1Database,
  items: Array<{ itemId: number; completedDate: string; workoutId: string; workoutData?: string }>
): Promise<void> {
  if (items.length === 0) return;
  await db.batch(
    items.map((item) =>
      db
        .prepare(
          "UPDATE queue_items SET status = 'completed', completed_date = ?, hevy_workout_id = ?, hevy_workout_data = ? WHERE id = ?"
        )
        .bind(item.completedDate, item.workoutId, item.workoutData ?? null, item.itemId)
    )
  );
}

export async function markQueueItemCompletedForUser(
  db: D1Database,
  itemId: number,
