/** All Hevy equipment categories + program-specific extensions (mapped to "other" at sync time) */
export type ExtendedEquipmentCategory =
  | "barbell" | "dumbbell" | "machine" | "cable" | "bodyweight"
  | "band" | "kettlebell" | "other" | "weighted_bodyweight"
  | "assisted_bodyweight" | "cardio" | "duration" | "resistance_band" | "none"
  | "foam_roller" | "pull_up_bar";

/** All Hevy muscle groups + program-specific extensions (mapped at sync time) */
export type ExtendedMuscleGroup =
  | "abdominals" | "abductors" | "adductors" | "biceps" | "calves"
  | "cardio" | "chest" | "forearms" | "full_body" | "glutes"
  | "hamstrings" | "lats" | "lower_back" | "neck" | "other"
  | "quadriceps" | "shoulders" | "triceps" | "traps" | "upper_back"
  | "hip_flexors" | "obliques";

export interface ExerciseTemplate {
  id: string;
  title: string;
  /** Hevy exercise type */
  type: "duration" | "reps_only" | "bodyweight_reps" | "weight_reps" | "weight_duration";
  equipmentCategory: ExtendedEquipmentCategory;
  primaryMuscleGroup: ExtendedMuscleGroup;
  secondaryMuscleGroups?: ExtendedMuscleGroup[];
  /** Coaching fields — not in Hevy */
  notes?: string;
  videoURL?: string;
  searchTerms?: string;
  tags?: string[];
  progressionByPhase?: Record<string, { sets?: string; notes?: string }>;
}

export interface RoutineExercise {
  exerciseTemplateId: string;
  /** The prescription for this routine context */
  sets: string;
  /** Override of template notes, if needed */
  notes?: string;
}

export interface Routine {
  id: string;
  title: string;
  subtitle?: string;
  description?: string;
  color?: string;
  isDaily?: boolean;
  sortOrder?: number;
  folderGroup?: string;
  exercises: RoutineExercise[];
}

export interface TemplateDay {
  dayOfWeek: number;
  label?: string;
  routineIDs?: string[];
}

export interface WeekTemplate {
  id: string;
  name: string;
  description?: string;
  sortOrder?: number;
  days: TemplateDay[];
}

// ──────────────────────────────────────────────────────────────────
// Extended program types — used by fragments for rendering
// ──────────────────────────────────────────────────────────────────

export interface Resource {
  id: string;
  title: string;
  url?: string;
  description?: string;
  category?: string;
}

export interface BodiRecommendedProgram {
  id: string;
  name: string;
  trainer?: string;
  duration?: string;
  fitLabel?: string;
  fitLabelColor?: string;
  description?: string;
  whenToUse?: string;
  cautions?: string;
  coupleFriendly?: boolean;
}

export interface BodiHybridDay {
  day: string;
  mobilitySession?: string;
  bodiSession?: string;
  notes?: string;
}

export interface BodiHybridSchedule {
  id: string;
  name: string;
  bodiProgramId?: string;
  description?: string;
  days: BodiHybridDay[];
}

export interface BodiIntegrationRule {
  id: string;
  rule: string;
  category?: string;
  priority?: number;
}

export interface BodiIntegration {
  id: string;
  title: string;
  description?: string;
  schedule?: string;
  notes?: string;
  recommendedPrograms?: BodiRecommendedProgram[];
  hybridSchedules?: BodiHybridSchedule[];
  integrationRules?: BodiIntegrationRule[];
}

export interface Program {
  meta: { title: string; subtitle?: string; description?: string; durationWeeks?: number };
  exerciseTemplates: ExerciseTemplate[];
  routines: Routine[];
  weekTemplates: WeekTemplate[];
  progressions: Progression[];
  roadmap?: RoadmapPhase[];
  skills?: Skill[];
  benchmarks?: Benchmark[];
  foundations?: Foundation[];
  resources?: Resource[];
  bodi?: BodiIntegration[];
}

export interface Progression {
