  if (dailyRoutine) {
    const dailyWorkout = workouts.find((w) => w.title === dailyRoutine.title);
    if (dailyWorkout) {
      await updateDailyCompleted(db, userId, toLocalDate(dailyWorkout.start_time, tz));
    }
  }

  await updateLastSyncAt(db, userId, new Date().toISOString());
}

